import struct, math, random
MOD = (1<<61) - 1

def frexp(x):
    bits = struct.unpack('>Q', struct.pack('>d', x))[0]
    exp = (bits >> 52) & 0x7FF
    if exp == 0:
        m, e = frexp(x * struct.unpack('>d', struct.pack('>Q', 0x4350000000000000))[0])
        return m, e - 54
    m_bits = (bits & ~(0x7FF << 52)) | (1022 << 52)
    m = struct.unpack('>d', struct.pack('>Q', m_bits))[0]
    return m, exp - 1022

def hash_float(v):
    if math.isnan(v):
        return 0
    if math.isinf(v):
        return 314159 if v > 0 else -314159
    if v == 0.0:
        return 0
    m, e = frexp(v)
    sign = 1
    if m < 0:
        sign = -1
        m = -m
    x = 0
    while m != 0.0:
        x = ((x << 28) & MOD) | (x >> (61 - 28))
        m *= 268435456.0
        e -= 28
        y = int(m)  # trunc toward 0
        m -= float(y)
        x += y
        if x >= MOD:
            x -= MOD
    if e >= 0:
        e = e % 61
    else:
        e = 61 - 1 - ((-1 - e) % 61)
    x = ((x << e) & MOD) | (x >> (61 - e))
    h = x * sign
    # wrapping mul in i64? x < 2**61, sign +-1, fits
    if h == -1:
        return -2
    return h

